pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // powers of two / common item sizes are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that fall into "harmonic" classes (multiples of 10, 20, 25, 50)
    if post_residual > 0 {
        if post_residual % 50 == 0 {
            score -= 12.0;
        } else if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        } else if post_residual % 10 == 0 {
            score -= 3.0;
        }
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Integer-division thresholds on post_residual: small dead zones are bad
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable dead space
    }

    // Coupling with next item: reward post_residual that can host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (next_item_size as f64) * 0.15;
        } else {
