            score -= 100.0;
        }
    }

    // Fractional capacity coupling: prefer filling bins past half capacity
    let fill_frac = 1.0 - pr / cap;
    score -= fill_frac * 8.0;

    // Stream progression: later in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * (0.2 + 0.3 * progress) * 0.1;

