    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let compat = (pr - ni).abs() / cap;
        score += 10.0 * compat * compat;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        }
    } else {
        // End of stream: prefer filling bins as completely as possible
        score += 5.0 * norm_post;
    }
    // Mild penalty for spreading across many bins relative to mean residual
    score += 2.0 * (open_bins_count as f64).ln() * norm_post;
    // Prefer bins below mean residual (denser bins) smoothly
    score += 3.0 * (mean_residual - pr) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (modulo 10 on capacity fractions) ---
    // Residuals divisible by 10 remain "usable" for typical future items; odd/tiny
    // fragments are dead space. Penalize dead-space classes, reward round classes.
    let cls = post_residual % 10;
    let class_penalty: f64 = match cls {
        0 => -6.0,               // perfectly reusable residual class
        1 | 2 | 3 => 3.0,        // sliver classes, nearly dead
        4 | 5 | 6 => 0.0,        // neutral mid classes
        7 | 8 | 9 => 1.5,        // awkward classes
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual / item_size ratio classes.
    if item_size > 0 {
        let ratio = post_residual / item_size.max(1);
        if ratio == 0 {
            // Very tight fit — excellent packing efficiency.
            score -= 25.0;
        } else if ratio == 1 {
            score -= 8.0; // item fills at least half of remaining space
        }
    }

    // Exact closure is the best possible outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Lookahead coupling (k=2): does the next item chain into this residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // perfect chain
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item divides the residual cleanly.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot use the leftover; leftover likely becomes dead space.
            score += 5.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Score a fresh bin by its own waste plus an opening tax; it wins only
        // when every open bin would waste more space than starting fresh.
        score = (bin_capacity - item_size) as f64 + 12.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // fresh bin leaves room for the lookahead item
        }
        if item_size >= 50 {
            score -= 4.0; // large items are fine to start fresh with
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading (penalize the new-bin option more).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).min(10.0);
    } else {
        score -= (open_bins_count as f64).min(10.0) * 0.2;
    }

    // Progress-aware nudge: late in the stream, tight fits matter slightly more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual <= 10 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable
    // for typical items (sizes >= 10 in the classic regime, but be safe for 1..100).
    let min_useful = 10.0f64;
    if (post_residual as f64) < min_useful {
        // Perfect fit gets strong reward; tiny unusable gap gets penalty.
        score -= 60.0; // post_residual == 0 => perfect fit bonus
    } else if (post_residual as f64) < 25.0 {
        // Dead zone: gap too small for most items -> penalize heavily.
        score += 40.0 - (post_residual as f64) * 0.8;
    }

    // Reward tight fits generally: score proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize leaving a gap that exactly matches the next item's size is good:
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 25.0; // lookahead: gap fits next item perfectly
        } else if gap >= nxt && gap - nxt < 10.0 {
            score -= 10.0; // next item leaves near-perfect follow-up
        } else if gap > 0.0 && gap < nxt {
            score += 15.0; // next item cannot use this bin anyway
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // (favor filling existing bins); when few bins are open, allow new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.6;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when current fit is poor or open-bin pressure is low.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < 10.0 || (bin_residual as f64) - (item_size as f64) > 0.6 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 25.0; // discourage opening new bins when a decent fit exists
        }
    }

    // Mild tie-break toward bins below mean residual (consolidate slack).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after two placements; penalize proportionally to dead space.
            let two_left = (post_residual - next_item_size) as f64;
            score += 0.6 * two_left;
            // Bonus if remaining space is small enough to be "dead" anyway (already tight).
            if two_left < 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here after placement; penalize tight-but-unusable residue.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are more precious,
    // avoid dumping large items into them unless it produces a near-perfect fit.
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 && post_residual > 0 {
        score += 0.25 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless residual capacity is genuinely needed
    // (e.g., current item barely fits nowhere well). New bin starts with large post_residual,
    // which already scores high; add mild extra penalty scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        // But if item is huge and no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty for very small dead space that fits nothing (typical range 10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to leftover gap
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the fit here is poor (large post residual anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - item_size as f64 / bin_capacity as f64;
        // new bin attractive only for large items or late in stream with many bins
        score += 20.0 * fit_quality * (1.0 - progress);
        score += 0.5 * (open_bins_count as f64).sqrt();
        if item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Reward using bins whose residual is below the mean (consolidating small residuals)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Slight preference for bins with residual close to item size (perfect-ish fit)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, prefer tighter packing (lower post_residual weighted more)
    let progress_weight = 1.0 + 1.5 * progress * progress;
    score *= progress_weight;

    // Penalty for dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual) / cap;
    score += 8.0 * dead * dead * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual (smooth)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0);
        let fit_frac = fits / cap;
        score += 10.0 * fit_frac * (1.0 - fit_frac); // smooth bump favoring usable leftovers
        score -= 5.0 * (next_item_size as f64 / cap) * (1.0 - norm_pr);
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: dead space in (0..10) is nearly unusable
    // since min item size is 10; class-based penalties.
    if post_residual > 0 {
        let class = post_residual % 10;
        // small leftover remainder is dead space
        score += (10 - class) as f64 * 1.5;
        // post_residual below 10 is total dead space: heavy penalty
        if post_residual < 10 {
            score += 60.0 + post_residual as f64 * 2.0;
        }
    }

    // Reward bins whose residual can host the next item (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + next_item_size as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // this placement destroys the only fit for next item in this bin
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets baseline score
    if bin_residual == bin_capacity {
        // neutral-ish base; worse late in stream when open bins exist and fit
        score = bin_capacity as f64 * 0.75;
        if fitting_bins_count > 1 {
            score += 80.0;
        }
        if open_bins_count == 0 {
            score -= 400.0;
        }
        // early stream: opening bins cheap to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        return score;
    }

    // Prefer filling fuller bins (tighter packing) via fraction of capacity
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Prefer bins with residual below mean (consolidate small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Integer division threshold: residual in [10,20) is a "harmonic slot"
    // that many small items can still use — mildly reward keeping it.
    if post_residual >= 10 && post_residual < 20 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    // Items are >= 1, but small gaps (1..=10) are hard to fill -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Gap slightly above 10 still risky if next item can't use it.
    if post_residual >= 10 && post_residual <= 20 {
        if (next_item_size as u32) > post_residual || next_item_size == 0 {
            score += 15.0;
        }
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the next item fits exactly in the post-residual, big bonus (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins,
    // penalize candidates that leave lots of residual when many bins are already open.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which adds open_bins_count pressure).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when all existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so we don't open bins casually; scale with stream progress.
        score += 70.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // If few bins are open, opening fresh is cheaper.
        if open_bins_count <= 2 {
            score -= 45.0;
        }
        // If next item is large, a fresh bin is more flexible.
        if next_item_size >= 50 {
            score -= 25.0;
        }
    }

    // Slight preference for bins below mean residual (balance spread).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect 2-step fit: post_residual == next_item_size -> strong reward
        let gap = (post - nxt).abs();
        if gap == 0.0 {
            score -= 60.0; // ideal: bin becomes exactly full after next item
        } else if nxt <= post {
            // next item fits: reward proportionally to tightness of the pair
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit in residual: penalize wasted pairing potential
            score += 10.0 + gap * 0.3;
        }

        // Coupling with mean residual: a bin whose post_residual deviates strongly
        // from the mean residual is either an outlier hole (bad) or near-full (good)
        let dev = (post - mean_residual).abs();
        score += 0.05 * dev;

        // Bonus when the pair leaves a residual that matches typical future needs
        // (post_residual close to mean_residual after a perfect pair is still fine)
        if gap == 0.0 {
            score -= 5.0 * (post / bin_capacity as f64);
        }
    } else {
        // Last item: pure best-fit on post_residual
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are open and fit exists:
    // new-bin candidate has bin_residual == bin_capacity; make it mildly unattractive
    if bin_residual == bin_capacity {
        // scale reluctance with stream progress and number of open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // but if item is large and leaves big dead space in any bin, new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Small penalty for large dead space (fragmentation avoidance)
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (1..100).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward;
    // if post-residual is almost enough but not quite, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size {
            score += 4.0;
        }
        // Perfect pairing: post_residual + next item nearly fills the bin
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 10.0;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 20.0 * tightness;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (14.0 - 20.0 * progress);

    // Many open bins with high mean residual: discourage new bins, encourage
    // filling existing ones; few open bins: allow spreading.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual * (open_bins_count as f64).sqrt();
    } else {
        score += 0.03 * mean_residual;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 5.0 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post-residual quality weighted by stream progress.
    // Tight fits (small post_residual) become more valuable as the stream progresses.
    let tightness = 1.0 - norm_pr;               // 1.0 = perfect fit
    let progress_gain = tightness * (0.5 + 2.0 * progress * progress);
    score -= 30.0 * progress_gain;

    // Penalize dead space quadratically, ramping with progress (smooth, no piecewise).
    score += 20.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 25.0 * progress;
    }

    // Lookahead coupling: reward if next item can fit into post-residual (smooth sigmoid-ish).
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let margin = (pr - next_item_size as f64).abs() / cap;
        score -= 15.0 * fits_next * (1.0 - margin);
        score += 8.0 * (1.0 - fits_next) * tightness * progress;
    }

    // Mild penalty for spreading across many open bins early; relaxes with progress.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose post-residual aligns with fleet mean.
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: bins whose leftover falls into
    // "reusable" classes (large enough for typical items) should be favored. ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = 1.0 - pr / c;

    // Reward high fill non-linearly (best-fit core, sharpened)
    score -= 3.0 * fill * fill;

    // --- Integer-division thresholds on post_residual ---
    // Dead-space classes: residual below the smallest item (<= ~10) is waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual <= 20 {
        score += 12.0; // narrow window, only tiny items fit
    } else if post_residual <= 34 {
        score += 4.0; // moderate
    } else if post_residual <= 50 {
        score -= 6.0; // sweet spot: half-bin leftover
    } else {
        score -= 2.0; // large leftover, still flexible
    }

    // --- Modulo arithmetic: harmonic compatibility with next item ---
    if next_item_size > 0 {
        let n = next_item_size;
        if post_residual >= n {
            // Exact / near-exact continuation fits are golden
            let slack = (post_residual - n) as f64;
            if slack == 0.0 {
                score -= 40.0; // perfect pair
            } else if slack <= 5.0 {
                score -= 20.0;
            } else if slack <= 15.0 {
                score -= 10.0;
            }
            // Harmonic residue: does post_residual mod next_item leave a good class?
            let residue = post_residual % n.max(1);
            if residue <= 5 {
                score -= 6.0; // leaves a near-dead but small remainder after next item
            } else if residue as f64 > 0.5 * n as f64 {
                score -= 3.0; // remainder still reusable
            }
        } else {
            // Next item cannot follow in this bin: leftover must stand alone
            if post_residual < 30 {
                score += 15.0; // likely stranded dead space
            }
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0; // strongly prefer using the only bin that fits
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0); // plenty of alternatives
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early when open bins are crowded, else discourage
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / c;
        if crowding < 0.25 {
            score -= 18.0 * (1.0 - progress); // open fresh capacity early
        } else {
            score += 10.0; // prefer packing into existing bins
        }
        // Never open a new bin when a near-perfect fit exists elsewhere
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // --- Mean-residual coupling: penalize bins far below mean (fragmenting) ---
    let dev = mean_residual - pr;
    if dev > 20.0 {
        score += 0.3 * dev; // this bin is much emptier than average -> poor choice
    } else if dev < -20.0 {
        score -= 0.2 * dev.abs(); // fuller than average -> good consolidation
    }

    // Mild bonus for tight fits relative to item size
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * ratio * ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (waste-free placement).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Prefer bins whose residual was already small (consolidate fullness).
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Pressure from too many open bins: favor filling existing bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New empty bin candidate: only attractive if item is large relative to capacity
    // or no bin fits well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 40.0 * frac;
        if next_item_size > 0 && (bin_residual as f64 - next_item_size as f64) >= 0.0 {
            // lookahead: opening a fresh bin may pair well with next item
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Lookahead: avoid leaving a gap that neither fits nor helps the next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size && (post_residual as u32) < next_item_size + 10 {
        score -= 20.0; // gap perfectly sized for next item
    }

    // Early stream: slight preference for keeping bins balanced.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * (1.0 - progress) * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (low post_residual) is good.
    // Normalize post_residual relative to capacity.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * post_frac * post_frac;

    // 2-step lookahead: reward when next_item_size fits exactly into post_residual
    // (perfect chain), penalize when next item cannot fit (dead space for the future).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item completion of this bin
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: partial reward scaled by how tight the chain is
            let slack_after_next = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - slack_after_next / bin_capacity as f64;
            score -= 35.0 * tightness;
        } else {
            // Next item does NOT fit here: post_residual becomes dead space
            // unless it matches some plausible size; penalize proportionally.
            let dead = post_residual as f64;
            score += 0.9 * dead;
            // Extra penalty if dead space is large but unusable (below min item size handled by range)
            if dead < 10.0 {
                score += 15.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item in stream: just minimize post residual aggressively
        score += 25.0 * post_frac;
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean (i.e., a tight bin) preserves large residuals elsewhere.
    let resid_frac = bin_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    score -= 20.0 * (mean_frac - resid_frac).max(0.0);
    score += 10.0 * (resid_frac - mean_frac).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer opening a new bin when no open bin offers a decent fit,
    // i.e., when the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for new bin; make it attractive only if item is big
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 60.0 * big_item;
        // If many bins are open and residuals are large, discourage new bin
        score += 8.0 * mean_frac;
        // Early in stream, new bins are cheap; late, avoid proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If next item is small, current bin leftovers may serve it; new bin less needed
        if next_item_size > 0 && next_item_size <= post_residual_of_new(item_size, bin_capacity) {
            score += 20.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

#[inline]
fn post_residual_of_new(item_size: u32, bin_capacity: u32) -> u32 {
    bin_capacity.saturating_sub(item_size)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for very small post-residual (good fills).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Penalize creating dead space that the next item cannot use.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer open bins unless this one is nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a bin is costly early; acceptable late when open bins are crowded.
        let crowding = mean_residual / (bin_capacity as f64);
        let open_penalty = 20.0 * (1.0 - progress) + 6.0 * open_bins_count as f64;
        score += open_penalty - 4.0 * (1.0 - crowding);
        // If no open bin fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild penalty when this bin's residual deviates far from the mean (balance pressure).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth quadratic dead-space penalty: waste grows super-linearly.
    let pr_norm = pr / cap;
    score += 1.5 * pr_norm * pr_norm * cap;

    // Reward tight fits with smooth cubic falloff of fit quality.
    let fit_quality = 1.0 - pr_norm;
    score -= 3.0 * fit_quality * fit_quality * fit_quality * it;

    // Stream-progress coupling: early on tolerate spread (favor new bins slightly),
    // later demand tight packing.
    let progress_coupling = 0.5 + 2.0 * progress * progress;
    score -= progress_coupling * fit_quality * cap * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin unnecessarily), smoothly scaled by scarcity.
    if fitting_bins_count <= 1 {
        score -= 8.0 + 4.0 * progress;
    } else {
        score += 2.0 / (fitting_bins_count as f64);
    }

    // Lookahead: if next item fits in the post-residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 2.0 * (1.0 - pr_norm) * (nxt / cap);
        } else {
            score += 1.5 * ((nxt - pr) / cap);
        }
    }

    // Mean-residual divergence: penalize bins far from the fleet average (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev * cap;

    // New-bin candidate handling: empty bin has pr = cap - item_size; if remaining
    // open bins are few or fit is poor, allow opening a new bin.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score -= 1.0 + 2.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "dead" classes (very small)
    // are penalized; leftovers in "pairable" classes are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries at capacity fractions: 0, 1/8, 1/4, 3/8, 1/2, 5/8, 3/4, 7/8, 1
    let frac = post / cap; // 0..1
    let class = (frac * 8.0).floor() as i32; // 0..8

    // Reward mid-size classes (usable by typical items 1..100), penalize tiny dead space
    match class {
        0 => score += 30.0,                 // dead space (< 12.5% left)
        1 => score += 10.0,
        2 => score -= 5.0,
        3 => score -= 12.0,                 // ~half-full bin, very flexible
        4 => score -= 12.0,
        5 => score -= 5.0,
        6 => score += 5.0,
        7 => score += 15.0,
        _ => {}                             // empty bin class (post == cap)
    }

    // Integer-division harmonic: residual modulo common item sizes.
    // If post_residual is divisible by small sizes, future small items fit perfectly.
    let pr = post_residual;
    if pr > 0 {
        let mut div_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                div_bonus += 6.0;
            }
        }
        score -= div_bonus;
    }

    // Lookahead coupling: penalize if next item cannot use this bin's post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item won't fit here regardless; slight penalty for wasting slot
            score += 8.0;
        } else if next_item_size == post_residual {
            score -= 25.0; // perfect lookahead pairing
        } else {
            let new_post = post_residual - next_item_size;
            // reward if the pair leaves a still-usable residual
            if new_post >= 10 {
                score -= 10.0;
            } else {
                score += 6.0; // pair creates dead space
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;
        // Early in the stream, or when many bins are open, be more willing to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If the mean residual across open bins is large, opening new bins is wasteful
        score += (mean_residual / cap).min(1.0) * 30.0;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += (bin_residual as f64 / cap) * 5.0;

    // Progress-aware dead-space tolerance: later in stream, squeeze harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.1 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps below the minimum item size (1..10 range) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range dead space (10..20) is risky too: few items fit.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 30.0 + 4.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 25.0; // an open bin could have taken it
        }
    } else {
        // Slight reward for filling existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Lookahead coupling: prefer bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fit (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual matches next item exactly
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size is highly desirable
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score += lookahead_gap * 0.35;
        }
        // Penalize if next item cannot fit in post_residual (dead space for next step)
        if post_residual < next_item_size {
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste
        score += 2.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are valuable, use them
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.20;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when post_residual would perfectly host next item
    // or no open bin is a good fit; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        } else {
            score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        }
    }

    // Slight penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: small post_residual that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // fits are poor. Give the empty bin a moderate baseline so good fits beat it.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many open bins with large mean residual, discourage another bin.
        score += 0.15 * open_bins_count as f64;
        score += 0.05 * mean_residual;
    }

    // Prefer filling bins whose residual is already small relative to the mean
    // (consolidate fragmentation).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.08 * diff;
        } else {
            score += 0.08 * (-diff);
        }
    }

    // Large items: place them promptly to avoid stranding them later.
    if item_size >= 60 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Smooth polynomial coupling: prefer small post residual, amplified later in stream
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score += 30.0 * poly * (0.5 + progress);

    // Non-linear progress interaction: tighten packing as stream advances
    score += 8.0 * progress * x;

    // Penalize large dead space quadratically, more strongly late in the stream
    score += 4.0 * x * x * (0.3 + progress * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 6.0 * fit_quality * (1.0 - progress);
        } else {
            score += 3.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Mild penalty for opening new bins when many bins are open and mean residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64 + 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity-fraction buckets.
    let frac = post_residual as f64 / cap;
    let class = (frac * 4.0).floor() as i32; // 0..3 (0=very tight, 3=very loose)

