    if pr % 5 == 0 { harmony += 1.5; }
    if pr % 10 == 0 { harmony += 2.0; }
    score -= harmony;

    // Integer division thresholds: residual in [0,10) is essentially dead space -> penalize.
    if post_residual < 10 {
