        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 25.0 - gap * 1.5; // near-perfect chaining
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual becomes dead space for the known next item: penalize
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        // extra reward if fit is tight
        if post_residual < 15 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    // (New-bin candidate has bin_residual == bin_capacity.)
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by how many are already open
        score += 20.0 + (open_bins_count as f64).sqrt() * 8.0;
        // but if existing bins are very fragmented (high mean residual spread),
        // a fresh bin is more attractive
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // reward using existing bins as open count grows
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Mild preference for tighter fits generally
    score -= item_size as f64 * 0.1;

    score
}

