pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Piecewise gap shaping (borrowed idea, retuned): very tight gaps strongly rewarded.
    if pr < 6.0 {
        score -= 90.0;
    } else if pr < 24.0 {
        score += 50.0 - pr * 1.3;
    } else if pr < 42.0 {
        score += (42.0 - pr) * 0.35;
    } else if pr < 70.0 {
        score += (pr - 42.0) * 0.06;
    } else {
        score += (pr - 70.0) * 0.11;
    }

    // Smooth quadratic dead-space penalty retained but weakened (gap shaping dominates).
    let pr_norm = pr / cap;
    score += 0.8 * pr_norm * pr_norm * cap;

    // Scarcity bonus: last fitting bin strongly favored.
    if fitting_bins_count <= 1 {
        score -= 9.0 + 4.0 * progress;
    } else {
        score += 2.0 / (fitting_bins_count as f64);
    }

    // Lookahead: exact next-fit reward, near-fit reward, mismatch penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 40.0;
        } else if pr >= nxt && pr - nxt < 14.0 {
            score -= 15.0;
        } else if pr > 0.0 && pr < nxt {
            if pr < 24.0 { score += 22.0; } else { score += 7.0; }
        }
        if pr >= nxt * 1.5 && pr < 60.0 {
            score -= 6.0;
        }
        if pr >= nxt && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        // Chain fit: item + next barely fits now.
        let chain = it + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 16.0;
        }
        if pr >= nxt + nxt && pr < nxt * 3.0 {
            score -= 5.0;
        }
        if pr >= nxt && pr - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 5.0;
        }
    }

    // Mean-residual divergence penalty (linear + quadratic under pressure).
    let dev = (pr - mean_residual) / cap;
    score += 0.20 * (mean_residual - pr) / cap * cap;
    if open_bins_count > 8 {
        score += dev * dev * 35.0 * cap / 100.0;
    }

    // Late-stream consolidation: tighten packing toward the end.
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 11.0 * progress;
    }

    // New-bin candidate handling with pressure gate.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let slack = cap - it;
        let poor_fit = slack > 0.60 * cap;
        let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
        let gate = 11.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && pr >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 38.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 34.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Small-residual dump bonus: nearly-full bins are cheap to top off.
    let res = bin_residual as f64;
    if res != cap {
        if res < it + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual (dead space).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * next_item_size as f64;
    }
