pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual)
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is more tolerable if it
    // falls into a "useful" residue class (multiples of common small sizes).
    let pr = post_residual as i64;
    let mut harmonic_bonus = 0.0;
    if post_residual == 0 {
        harmonic_bonus -= 60.0; // perfect fit, huge reward
    } else {
        // post_residual divisible by small item sizes => future items may fill it
        for m in [5u32, 10, 20, 25, 50].iter() {
            if pr % *m as i64 == 0 {
                harmonic_bonus -= 8.0;
            }
        }
        // post_residual itself in "fillable" range: 10..80 items can land there
        if post_residual >= 10 && post_residual <= 80 {
            harmonic_bonus -= 10.0;
        } else {
            // dead space: too small for any item but nonzero
            harmonic_bonus += 25.0;
        }
        // Quotient threshold: integer division of residual by item size
        let q = pr / item_size.max(1) as i64;
        harmonic_bonus -= 3.0 * q as f64;
    }
    score += harmonic_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic match: next_item divides post_residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
