}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let gap = pr;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post residual with non-linear compression (dead space hurts when large).
    let mut score = gap * (1.0 + 0.5 * (gap / cap).powi(2));

    // Piecewise gap shaping (borrowed strength: tight fits strongly rewarded).
    if gap < 6.0 {
        score -= 92.0;
    } else if gap < 24.0 {
        score += 54.0 - gap * 1.35;
    } else if gap < 42.0 {
        score += (42.0 - gap) * 0.36;
    } else if gap < 70.0 {
        score += (gap - 42.0) * 0.06;
    } else {
        score += (gap - 70.0) * 0.11;
    }

    // Perfect fit reward (smooth).
    let perfect = 1.0 - (gap / cap);
    score -= 15.0 * perfect * perfect * perfect;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * (item_size as f64 / cap);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (gap - n).abs() < 0.5 {
            score -= 42.0;
        } else if gap >= n && gap - n < 14.0 {
            score -= 16.0;
        } else if gap > 0.0 && gap < n {
            if gap < 24.0 { score += 24.0; } else { score += 7.0; }
        }
        if gap >= n * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= n && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        let chain = item_size as f64 + n;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 18.0;
        }
        if gap >= n + n && gap < n * 3.0 {
            score -= 5.0;
        }
        if gap >= n && gap - n < 7.0 && fitting_bins_count > 1 {
            score -= 5.0;
        }
        // Smooth progress-coupled room reward retained from parent.
        let room = (gap - n) / cap;
        if room >= 0.0 {
            score -= 4.0 * room * (1.0 - progress);
        } else {
            score += 3.0 * (-room);
        }
    }

    // Penalize bins far from mean residual (avoid fragmenting the pool unevenly).
    let res = bin_residual as f64;
    let dev = (res - mean_residual) / cap;
    score += 5.0 * dev * dev;
    if open_bins_count > 8 {
        score += dev * dev * 35.0;
    }
    score += 0.20 * (mean_residual - res);

    // Late-stream pressure: prefer filling existing bins harder.
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 11.0 * progress;
    }

    // New-bin candidate: open only when fit is poor AND pressure is low.
    if bin_residual == bin_capacity {
        let slack = cap - item_size as f64;
        let poor_fit = slack > 0.60 * cap;
        let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
        let gate = 11.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 40.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 34.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items (1..=10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Mildly awkward gap.
        score += 4.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 12.0;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.3;
        // Early in stream, new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Slight nudge toward bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

