pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus that grows as post_residual shrinks.
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        score -= 60.0; // perfect fit
    }

    // Dead space penalty: residual too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after that hypothetical placement
            let after2 = post_residual - next_item_size;
            score += 0.3 * after2 as f64;
            if after2 == 0 { score -= 10.0; }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (fill the fullest bins first, keep large residual bins flexible).
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great
    // 2-step chain (next item fits perfectly in a fresh bin).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 15.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let after2 = bin_capacity - item_size - next_item_size;
            if after2 == 0 {
                new_bin_score -= 60.0; // fresh bin chains perfectly with next item
            } else if after2 < 10 {
                new_bin_score += 10.0;
            }
        }
        if next_item_size == 0 {
            new_bin_score += 20.0; // no lookahead benefit at stream end
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a nonlinear tilt.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward for a near-perfect chain fit.
            let chain_gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - chain_gap as f64 / bin_capacity as f64);
        } else {
            // Penalize creating dead space the next item can't use.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 4.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Crowd penalty: with many open bins, prefer filling existing ones harder.
    let open_f = open_bins_count as f64;
    score -= 1.5 * (open_f / (open_f + 5.0)) * tightness;

    // Mean-residual coupling: if global residuals are high, be pickier about waste.
    let waste_excess = (post_residual as f64 - mean_residual).max(0.0);
    score += 0.05 * waste_excess;

    // Time horizon: early in the stream, keep bins flexible (penalize tiny residuals);
    // late in the stream, just pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10.0 {
        score += 4.0 * (1.0 - progress); // tiny slivers hurt early (long future)
    }
    score -= 3.0 * progress * tightness;

    // New-bin candidate: only attractive when item barely fits anywhere or residuals are low.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 10.0 - 14.0 * desperation - 6.0 * progress;
        // If the next item is huge and this item is small, a fresh bin preserves structure.
        if next_item_size > 60 && item_size < 40 {
            score -= 5.0;
        }
    }

    score
}

