pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr - 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth progress coupling: later in stream, penalize large residuals more (less time to fill them).
    let late = progress * progress;
    score += 50.0 * late * norm_pr;

    // Reward tight fits smoothly (small post_residual relative to item size).
    let it = item_size as f64;
    let tight = 1.0 - pr / (bin_residual as f64 + 1.0);
    score -= 20.0 * tight * tight * (it / cap);

    // Lookahead: bonus if next item fits the post residual (smooth decay with gap).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 15.0 * gap * gap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Crowd control: many open bins -> prefer filling existing ones.
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 10.0 * crowd * (1.0 - norm_pr);

    // Deviation from mean residual: prefer bins near the mean (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

