pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets
    // via integer division on a small quantum (items >= 10 typically).
    let q = 10u32;
    let class = post_residual / q; // 0..=10
    // Dead-space classes that are nearly unusable get a strong penalty.
    if post_residual < 10 {
        score += 40.0; // tiny sliver, almost guaranteed waste
    } else if class <= 2 {
        score += 12.0; // 10..29 residual: risky, fits few item sizes
    } else if class <= 4 {
        score += 4.0; // 30..49: moderate
    } else if class <= 6 {
        score -= 3.0; // 50..69: good class
    } else {
        score -= 6.0; // 70..100: excellent, near-empty bin kept flexible
    }

    // Perfect-fit harmonic bonus: post_residual exactly divisible by common
    // item quanta (10, 20, 25) suggests future items can tile it.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 5.0; }
        else if post_residual % 25 == 0 { score -= 3.0; }
        else if post_residual % 20 == 0 { score -= 2.0; }
        else { score += (post_residual % 10) as f64 * 0.4; }
    }

    // Lookahead coupling: reward if post_residual can still hold next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // this placement strands the lookahead item
        }
        // Exact match with next item is a harmonic jackpot.
        if post_residual == next_item_size { score -= 10.0; }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless open bins are crowded
    // or this bin would be a poor fit anyway.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 0.8;
        let poor_fit = if post_residual < 20 { 10.0 } else { 0.0 };
        score += 25.0 + crowded - poor_fit;
        // Early in stream, opening bins is cheap; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure toward bins tighter than the mean (compact packing).
    let res_f = bin_residual as f64;
    if res_f < mean_residual { score -= 2.0; } else { score += 1.5; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Treat residual < 10 as unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; if post residual almost fits next item,
    // slight penalty (near miss creates temptation/waste).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else if post_residual > 0 && next_item_size - post_residual <= 5 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin is costly, but acceptable
    // when this bin would create bad dead space or the item barely fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // If no other bin fits, opening is the only choice: soften penalty.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Large remaining stream: keep open-bin count lean.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    } else {
        // Reward using existing bins, more so when few fitting bins remain.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // tight fits to close bins out.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is far below the mean (tight bins),
    // spreading items over loose bins.
