    score -= 8.0 * perfect * perfect * perfect;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * (item_size as f64 / cap);
    }

    // Lookahead: exact-fit chain for next item.
