    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 800.0; // perfect chain: item + next fill bin exactly
        } else if next_item_size <= post_residual {
            let slack = pr - nx;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item does NOT fit in this bin's remainder: penalize dead space
            let waste = nx - pr;
            score += 150.0 + 4.0 * waste;
        }
    }

    // Penalize leaving residuals that are hard to fill (small odd gaps relative to mean).
    if pr > 0.0 && pr < 10.0 {
        score += 200.0 * (10.0 - pr) / 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin should only win when this bin's
    // fit is bad. Give the empty bin a baseline penalty that scales with how full
    // the fleet already is (encourage consolidation late in stream).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 400.0 + 300.0 * progress;
        // but if next item is large and would pair with this item, opening a fresh
        // bin is more attractive
        if next_item_size >= item_size {
            score -= 100.0;
        }
    }

    // Mild coupling to mean residual: prefer bins below mean residual (tighter bins)
    // to preserve large residuals elsewhere for big future items.
    if (bin_residual as f64) > mean_residual {
        score += 20.0;
    } else {
        score -= 10.0;
    }

    // Slight preference for using more-open-bins situations (avoid bin explosion)
    if open_bins_count > 10 {
        score -= (open_bins_count as f64).min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer minimal waste after placement.
    let mut score = post;

    // Reward tight fits non-linearly: bonus grows as post_residual shrinks.
    let fit_ratio = 1.0 - (post / cap);
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that likely can't serve future items:
    // small post_residual (<10) is near-waste unless it's exactly tight.
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 45.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 {
            (mean_residual / cap).min(1.0)
        } else {
            0.0
        };
        // Penalty when plenty of open bins have room; discount as they fill.
        score += 40.0 * (1.0 - crowded);
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Opening a bin is fine for big items.
        score -= 15.0 * (item / cap);
    } else {
        // Mild preference for keeping bins balanced vs. mean residual.
        score += 0.15 * (post - mean_residual).abs();
    }

    // Slight reward for placing into bins with larger pre-residual (consolidation).
    score -= 0.05 * residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
