    } else if gap < 24.0 {
        score += 54.0 - gap * 1.35;
    } else if gap < 42.0 {
        score += (42.0 - gap) * 0.36;
    } else if gap < 70.0 {
        score += (gap - 42.0) * 0.06;
    } else {
        score += (gap - 70.0) * 0.11;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect 2-step match
        if (gap - nxt).abs() < 0.5 {
            score -= 42.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 16.0;
        } else if gap > 0.0 && gap < nxt {
            // Dead space: too small for next item
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0 + (nxt - gap) * 0.5;
            }
        }
        // Roomy enough to host next item too
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        // Chain fit: item + next exactly consumes bin
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 18.0;
        }
        if gap >= nxt + nxt && gap < nxt * 3.0 {
            score -= 5.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 5.0;
        }
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.60 * bin_capacity as f64;
        let gate = 11.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
