            score -= 3.0;
        } else {
            score += 34.0;
        }
    }

    // Balance against mean residual
    score += 0.20 * (mean_residual - bin_residual as f64);

    // Late-stream tightening
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 11.0 * progress;
    }

    // Residual deviation shaping
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 35.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    score
}

