        score += 30.0; // dead space penalty
    } else if post_residual < quarter {
        score += 12.0;
    }

    // Modulo arithmetic: residuals congruent to 0 mod 10 are "aligned"
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
