        if res < 12.0 && next_item_size as f64 > res {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is disproportionately bad).
    if post_residual <= 5 {
        score -= 40.0 * (6 - post_residual) as f64;
    } else if post_residual <= 12 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits here afterwards: strong reward for tight chaining.
            score -= 30.0 - 1.5 * gap;
        } else {
            // Next item would not fit: penalize proportionally to overflow.
            score += 0.8 * gap;
        }
        // Perfect chain bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: only exactness matters.
        score += 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if lookahead chains perfectly into a fresh bin, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Late in the stream: consolidate, penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64 / 10.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / cap;
    score += tightness * 30.0;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; slight penalty if we leave a large awkward gap.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += gap * 0.2;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer filling bins with large residuals (consolidate emptiness).
    score -= (bin_residual as f64 / cap) * 10.0;

    // Global state: many open bins -> discourage opening new ones, encourage filling.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 20.0 + 15.0 * pressure;
        // But allow a new bin if the item is huge and fits poorly everywhere.
        if item_size > 70 {
            score -= 15.0;
        }
    } else {
        score -= 5.0 * pressure.min(2.0);
    }

    // Time horizon: early in stream, be conservative with new bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mean residual coupling: if mean residual is low (bins nearly full), favor using existing bins.
    if bin_residual < bin_capacity {
        score -= (mean_residual / cap) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let gap = post_residual as f64 ;
    if gap < 6.0 { score -= 92.0 ; }
    else if gap < 24.0 { score += 54.0 - gap * 1.35 ; }
    else if gap < 42.0 { score += (42.0 - gap) * 0.36 ; }
    else if gap < 70.0 { score += (gap - 42.0) * 0.06 ; }
    else { score += (gap - 70.0) * 0.11 ; }
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if (gap - nxt).abs() < 0.5 { score -= 42.0 ; }
        else if gap >= nxt && gap - nxt < 14.0 { score -= 16.0 ; }
        else if gap > 0.0 && gap < nxt {
            if gap < 24.0 { score += 24.0 ; } else { score += 7.0 ; }
        }
        if gap >= nxt * 1.5 && gap < 60.0 { score -= 6.0 ; }
        if gap >= nxt && fitting_bins_count <= 2 { score -= 8.0 ; }
        let chain = item_size as f64 + nxt ;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 { score -= 18.0 ; }
        if gap >= nxt + nxt && gap < nxt * 3.0 { score -= 5.0 ; }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 { score -= 5.0 ; }
        // lookahead: prefer bins whose gap can host next two items tightly
        if gap >= nxt && gap - nxt > 14.0 && gap < nxt * 2.0 && fitting_bins_count > 3 {
            score += 4.0 ;
        }
    }
    let progress = step_index as f64 / (total_items.max(1) as f64) ;
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress) ;
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64 ;
        let poor_fit = slack > 0.60 * bin_capacity as f64 ;
        let gate = 11.0 - 4.0 * progress ;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64 ;
        if poor_fit && pressure < gate && ! leftover_hosts_next { score -= 40.0 ; }
        else if poor_fit { score -= 3.0 ; }
        else { score += 34.0 ; }
        // refine new-bin gate: at high pressure, mildly discourage opening unless very tight fit
        if progress > 0.5 && ! poor_fit {
            score += 6.0 * progress ;
        }
    }
    score += 0.20 * (mean_residual - bin_residual as f64) ;
    if progress > 0.72 && bin_residual != bin_capacity { score -= 11.0 * progress ; }
    let res = bin_residual as f64 ;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64 ;
        score += dev * 6.0 ;
        if open_bins_count > 8 { score += dev * dev * 35.0 ; }
        if res < item_size as f64 + 4.0 { score -= 4.0 ; }
        if res < 12.0 && next_item_size as f64 > res { score -= 6.0 ; }
        // penalize mid-range dead space more when many bins are open
        if res > 20.0 && res < 45.0 && open_bins_count > 12 {
            score += (45.0 - res) * 0.15 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (low post_residual), with a mild convexity so
    // very small post residuals are extra attractive (dead-space shaping).
    let mut score = post + 0.15 * (post * post) / cap;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (bins are "committed").
    let progress_coupling = 1.0 + 1.2 * progress * progress;
    score *= progress_coupling;

    // Reward filling a bin nearly completely, more strongly as stream advances.
    let fill = 1.0 - post / cap;
    score -= (2.0 + 3.0 * progress) * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin, scaled smoothly by how well it fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 8.0 * fill;
    }

    // New-bin candidate handling: an empty bin should lose unless the fit
    // elsewhere would leave a large, awkward residual relative to future need.
    if bin_residual == bin_capacity {
        // Slight preference for new bins early (diversification), penalty later.
        score += 3.0 - 6.0 * progress;
        // If next item could use the leftover of a tight fit elsewhere,
        // penalize opening a new bin when a good fit exists.
        let next = next_item_size as f64;
        if next > 0.0 {
            let wasted_if_here = (cap - item).min(cap);
            let next_fits_waste = if wasted_if_here >= next { 1.0 } else { 0.0 };
            score += 2.0 * next_fits_waste * (1.0 - progress);
        }
    } else {
        // Lookahead synergy: if the next item exactly matches this bin's
        // post-residual, reward placing current item here.
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 4.0 + 4.0 * progress;
        } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            // smooth partial reward proportional to how much slack remains for next
            score -= 1.5 * (next_item_size as f64 / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    // (encourages consolidation), coupled smoothly with post residual.
    let mean_r = mean_residual.max(0.0);
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (post / cap) * (1.0 + mean_r / cap);

    // Tiny deterministic tie-breaker based on residual parity structure.
    score += 0.001 * ((post_residual % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let gap = post_residual as f64;

    // Piecewise shaping of post-residual (borrowed tightening from best)
    if gap < 6.0 {
