        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 18.0;
        }
        // Two next-items fit
        if gap >= nxt + nxt && gap < nxt * 3.0 {
            score -= 5.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 5.0;
        }
    }

    // New-bin candidate logic with pressure gating
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.60 * bin_capacity as f64;
        let gate = 11.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 40.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 34.0;
        }
    }

    // Balance against mean residual
    score += 0.20 * (mean_residual - gap);

    // Late-stream: consolidate into existing bins
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 11.0 * progress;
    }

    // Deviation penalty on open bins
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 35.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild progress scaling retained from parent
    score *= 1.0 + 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Leftovers in "usable" bands (>= ~1/3 of a
    // typical item) are far more valuable than tiny slivers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: tiny nonzero leftovers are nearly unusable
    // (items are 1..=100, so anything < 12 is likely waste).
    if pr < 12.0 {
        score += 400.0;
    } else {
        // Integer-division harmonic classes: bucket post_residual by quarters.
        let quarter = (post_residual * 4) / bin_capacity; // 0..3
        let class_bonus: f64 = match quarter {
            0 => 150.0, // 0-25% leftover: cramped but small waste
            1 => 0.0,   // 25-50%: sweet spot
            2 => -20.0, // 50-75%: roomy, good
            _ => -40.0, // 75-100%: nearly empty bin, very reusable
        };
        score += class_bonus;

        // Modulo arithmetic on residual: leftovers divisible by common item
        // granularities (10, 20, 25) are more likely to be filled exactly.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 25.0;
            if r % 50 == 0 {
                score -= 15.0;
            }
        }
        if r % 25 == 0 {
            score -= 12.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // Fraction of leftover consumed by next item: harmonic coverage.
            let coverage = nxt / pr;
            score -= 120.0 * coverage;
            // Penalize leaving a sliver smaller than next item (double dead space).
            if post_residual - next_item_size < 12 {
                score += 60.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap).min(1.0) * 80.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all open
    // bins have bad fits. Scale slightly with stream progress and crowding.
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.10 * mean_residual + (open_bins_count as f64).powf(0.5) * 3.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        return score;
    }

    // Prefer tighter bins slightly (best-fit flavor) modulated by crowding.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

