    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // medium-small gap: moderate penalty unless next item fits
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    } else if post_residual >= 20 {
        // large gap is reusable; reward if the lookahead item fits it
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 30.0;
        }
    }

    // Open-bins pressure: when many bins are open, discourage opening/spreading;
