    // New-bin candidate: only attractive when current bin fit would be terrible
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit {
            score -= 40.0; // prefer fresh bin over creating dead space
        } else {
            score += 50.0; // discourage opening new bins on decent fits
        }
