pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (-8.0 * tightness).exp();

    // Penalize dead space that no future item (min size 1..~10) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers are wasteful
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 5.0; // still potentially fillable by small items
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over stream horizon.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 10.0 * progress;
        // If many open bins with lots of residual space, discourage new bins.
        score += 0.5 * open_bins_count as f64;
        // If mean residual is large, new bin is wasteful.
        score += 0.3 * mean_residual;
        // But if next item is huge and current fits are tight, allow new bin.
        if next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild preference for filling bins that are already more full than average.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
    score -= 6.0 * (fullness - mean_fullness);

    // Time-horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // Tie-break by bin index proxy: prefer bins with less residual among equals.
    score += 0.01 * bin_residual as f64;

    score
}

