    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual, with a non-linear (quadratic) sharpening
    // so near-perfect fits are disproportionately favored.
    let mut score = post + (post / cap).powi(2) * cap * 0.5;

    // Smooth stream-progress coupling: early on, be more tolerant of leftover
    // space (plenty of future items can fill it); late, penalize waste more.
    let urgency = 0.5 + 1.5 * progress * progress;
    score *= urgency;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // are dead weight; apply a smooth sigmoid-like bump around cap/10.
    let dead = ((cap * 0.1 - post) / (cap * 0.1)).clamp(0.0, 1.0);
    score += dead * dead * 12.0;

    // Lookahead coupling: if the next item fits the post residual, reward;
    // smooth compatibility term rather than a hard piecewise branch.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = (nx / (post + 1.0)).clamp(0.0, 1.0);
        let slack = (post - nx).abs() / cap;
        score -= compat * (1.0 - slack) * 8.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count <= 1 {
        score -= 10.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate: make it moderately unattractive unless the item is
    // large relative to capacity (large items deserve fresh space) or late
    // in the stream when many bins are open anyway.
    if bin_residual == bin_capacity {
        let large_item = (item / cap).clamp(0.0, 1.0);
        let crowding = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).clamp(0.0, 1.0);
        score = 25.0 + 30.0 * (1.0 - large_item) * (1.0 - 0.6 * crowding) - 15.0 * progress;
