    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap % 10 == 0 {
            score -= 8.0;
        }
        if gap == 0 {
            score -= 12.0;
        }
        // next item fills a harmonic fraction of the post-residual
        let frac = next_item_size as f64 / post_residual as f64;
        if (frac * 4.0).round() / 4.0 == frac {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally
        score += (next_item_size as f64) * 0.15;
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 10;
    match q {
        0 => score -= 15.0,           // near-perfect fill
        1 => score -= 6.0,
        2 | 3 => score += 2.0,        // awkward mid residual
        _ => {}
    }
    if post_residual > 50 {
        score += 5.0;                 // wasting more than half a bin
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let base = 45.0;
        score = base + (post_residual as f64) * 0.1;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for lookahead pairing in fresh bin
