    }

    // Tightness coupling: reward small post_residual relative to capacity.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Late-stream consolidation: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.3;
    score += (mean_residual - post_residual as f64) * 0.05;

    score
