    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item truly fits nowhere well.
        score += 25.0 + 8.0 * open_bins_count as f64 * (0.4 + 0.6 * progress);
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 30.0; // lookahead item cannot fit mean residual; fresh bin useful
        }
    } else {
        // Mild bonus for consolidating into existing bins when many are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead synergy: leaving exactly enough room for the next item is great.
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit) among open bins.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small dead space quadratically (avoid leaving unusable gaps).
    score += (post_residual as f64).powi(2) / 100.0;

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // If next item fits into post_residual, mild reward proportional to tightness.
    else if next_item_size > 0 && next_item_size < post_residual {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 50.0 * tight;
    }
    // If next item cannot fit in the post residual, penalize large leftovers.
    else if next_item_size > post_residual {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are large
    // relative to the item (i.e., no open bin is a good home).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let pressure = if next_item_size > 0 {
            (next_item_size as f64) / (bin_capacity as f64)
        } else {
            0.0
        };
        // Base penalty so real bins usually win; reduced when mean residual is tight.
        score += 250.0 + 10.0 * openness - 0.3 * mean_residual - 100.0 * pressure;
        // If this is the only fitting option (no open bins fit), remove penalty.
        if fitting_bins_count == 1 {
            score -= 400.0;
        }
    }

    // Late in the stream, consolidate: penalize keeping many bins open.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 0.2 * open_bins_count as f64 * progress;
    }

    score
}

