pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Progress through the stream: early on, be more willing to open/spread;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small for the smallest plausible item are waste.
    if post_residual < 10 {
        score += 25.0 * (1.0 - progress); // early waste is less forgivable later? invert: late waste is worse
        score += 20.0 * progress;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            score += 3.0;
        }
        // Perfect chain: this item plus next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Crowding: many open bins with high mean residual -> favor consolidating into
    // already-large-residual bins to empty others out.
    if open_bins_count > 2 {
        let mean_gap = mean_residual - bin_residual as f64;
        score += 0.15 * mean_gap * (open_bins_count.min(20) as f64 / 20.0);
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it only wins
    // when fits into open bins are truly bad (large post_residual).
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If no open bin fits at all, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for bins whose residual is "awkward" (just above item size),
    // consuming them before they become dead space.
    let awkward = (bin_residual as f64 - item_size as f64).min(item_size as f64);
    score -= 0.1 * awkward;

    // Time-horizon term: as stream matures, penalize leaving large residuals in
    // many bins (fragmentation).
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr as f64;

    // Smooth polynomial coupling: dead-space penalty grows non-linearly with stream progress
    // (early on, wasted space is more forgivable; later, tightness matters more)
    let tightness_reward = -40.0 * (1.0 - norm_pr * norm_pr) * (0.4 + 0.6 * progress);
    score += tightness_reward;

    // Penalize very small unusable residuals via smooth quartic bump around tiny residuals
    let tiny = (1.0 - norm_pr).min(0.2) / 0.2;
    score += 25.0 * tiny * tiny * (1.0 - tiny) * (1.0 - tiny) * progress;

    // Lookahead coupling: reward leaving space that next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 15.0 * fit_quality * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty when many bins are open and this bin is near-empty (encourage consolidation)
    let emptiness = 1.0 - bin_residual as f64 / cap;
    score += 10.0 * (1.0 - emptiness) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Deviation from mean residual: prefer bins whose residual is close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 12.0 * dev * dev * progress;

    // New-bin candidate: make empty bin moderately attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - item_size as f64 / cap) - 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let gap = post_residual as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Fine-grained residual shaping (borrowed graded curve, replaces coarse bands)
    if gap > 0.0 {
        if gap < 6.0 {
            score -= 92.0;
        } else if gap < 24.0 {
            score += 54.0 - gap * 1.35;
        } else if gap < 42.0 {
            score += (42.0 - gap) * 0.36;
        } else if gap < 70.0 {
            score += (gap - 42.0) * 0.06;
        } else {
            score += (gap - 70.0) * 0.11;
        }
    }

    // Lookahead: exact-fit chains for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 42.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 16.0;
        } else if gap > 0.0 && gap < nxt {
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0;
            }
        }
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 18.0;
        }
        // two-of-next lookahead
        if gap >= nxt + nxt && gap < nxt * 3.0 {
            score -= 5.0;
        }
        // tight leftover that still hosts next again
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 5.0;
        }
        if gap >= nxt && gap - nxt < 10.0 && gap - nxt >= nxt {
            score -= 4.0;
        }
    }

    // Open-bins pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
    score += pressure * 0.4;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: open fresh bin only when the fit would be terrible,
    // gated by pressure and whether leftover could host the next item
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.60 * bin_capacity as f64;
        let gate = 11.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 40.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 34.0;
        }
    }

    // Mean residual coupling
    score += 0.20 * (mean_residual - bin_residual as f64);

    // Late-stream tightening: prefer filling existing bins near the end
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 11.0 * progress;
    }

    // Residual deviation shaping for open bins
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 35.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 6.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fraction bands.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Perfect fits (residual in {0}) are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic "dead zone": tiny residuals (1..=9) are nearly unusable dead space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }

    // Modulo classes: residuals divisible by 10 are "harmonic" slots
    // (likely to exactly accept future 10-multiple items).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here; penalize proportionally to waste.
            score += 15.0;
        }
        // Harmonic modulo match: next_item_size divides post_residual evenly.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize opening unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 120.0
            - 80.0 * (mean_residual / cap)
            + 10.0 * open_bins_count as f64;
        // If next item is large and residuals are tight, opening fresh is fine.
        if next_item_size >= 60 {
            score -= 60.0;
        }
    }

    // Tightness reward: the fuller the bin becomes, the better.
    score -= (1.0 - frac) * 20.0;

    // Progression bias: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

