pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted.
    // Penalize post_residuals that are too small to ever hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: unusable sliver
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 18.0; // marginal gap: only tiny items fit
    } else if post_residual == 0 {
        score -= 55.0; // perfect fit, strongly reward
    }

    // Reward bins whose post_residual can still hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 12.0; // leftover can't fit next item: likely dead
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and progress.
        score += 45.0 + 8.0 * open_bins_count as f64 + 25.0 * progress;
        // Allow new bin if item is huge and fits poorly anywhere (rare).
        if item_size > 70 && open_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // Mild bonus for filling bins that are already quite full.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fullness;
        // Slight reward for using bins below the mean residual (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    score
