    }

    // Open-bin pressure grows with progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.85 * progress);

    // New-bin candidate logic: open only when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
