    } else if gap < 24.0 {
        score += 54.0 - gap * 1.35;
    } else if gap < 42.0 {
        score += (42.0 - gap) * 0.36;
    } else if gap < 70.0 {
        score += (gap - 42.0) * 0.06;
    } else {
        score += (gap - 70.0) * 0.11;
    }

    // Lookahead: exact-fit chains for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 42.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 16.0;
        } else if gap > 0.0 && gap < nxt {
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0;
            }
        }
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 8.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 18.0;
        }
        if gap >= nxt + nxt && gap < nxt * 3.0 {
            score -= 5.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 5.0;
        }
        // leftover after next item stays small and reusable
        if gap >= nxt && gap - nxt < 10.0 && gap - nxt >= nxt {
            score -= 4.0;
        }
    }

    // Open-bins pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
    score += pressure * 0.4;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: open fresh bin only when the fit would be terrible
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.60 * bin_capacity as f64;
        let gate = 11.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
