        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 6.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual buckets of size 10
    let class = post_residual / 10;
    // Penalize residuals that fall in "dead" classes (1..=9) — too small for most items (min size 1..100 unknown, but classic packing dead zones)
    match class {
