        3 | 4 => score += 2.0,
        5 => score -= 4.0,                // half-full bin is reusable
        6 | 7 => score -= 2.0,
        _ => {}
    }

    // Modulo coupling: residuals divisible by common item sizes are more reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 3 == 0 { score -= 1.0; }
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
