        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 22.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 7.0;
        }
        if gap >= nxt {
            let after = gap - nxt;
            if after > 0.0 && after <= 6.0 {
                score -= 16.0;
            } else if after >= 10.0 && after <= 20.0 {
                score -= 8.0;
            } else if after > 50.0 {
                score += 5.0;
            } else if after > 34.0 && after < 50.0 {
                score += 2.5;
            }
        }
        if gap >= nxt + nxt && (gap - nxt - nxt) < 6.0 {
            score -= 11.0;
        }
        if gap > 0.0 && gap < nxt && fitting_bins_count <= 1 {
            score += 10.0;
        }
    }

    // Open-bins pressure
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);

    // Only-bin reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: open fresh bin only when the fit would be terrible
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.56 * bin_capacity as f64;
        let gate = 12.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 46.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 38.0;
        }
        if open_bins_count > 14 && poor_fit {
            score -= 8.0;
        }
        // Refined late-stream gating: keep fresh bins unattractive as stream ends
        if progress > 0.8 && slack > 0.45 * bin_capacity as f64 {
            score += 14.0;
        }
        if progress > 0.85 && slack > 0.3 * bin_capacity as f64 {
            score += 20.0;
        }
        if progress > 0.25 && progress < 0.7 && mean_residual > 30.0 && slack > 0.4 * bin_capacity as f64 {
            score += 8.0;
        }
        // New: avoid opening a bin whose slack cannot host the next item mid-stream
        if progress > 0.35 && progress < 0.85 && next_item_size > 0
            && slack > 0.2 * bin_capacity as f64
            && slack < next_item_size as f64 {
            score += 10.0;
        }
    }

    // Mean residual coupling
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late-stream tightening
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 14.0 * progress;
    }

    // Residual deviation shaping for open bins
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 38.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 7.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 4.0;
        }
        if res > 70.0 && next_item_size as f64 > res {
            score += 6.0;
        }
        if res > 45.0 && res < 70.0 && next_item_size as f64 > res && progress > 0.3 {
            score += 3.0;
        }
        // Zero-waste handoff
        if next_item_size > 0 && (res - next_item_size as f64).abs() < 1.0 {
            score -= 7.0 + 4.0 * progress;
        }
        // Near-miss residual: next item barely misses this bin
        if next_item_size > 0 && res < next_item_size as f64 && next_item_size as f64 - res <= 5.0 {
            score += 4.0;
        }
        // Mean-aligned reusable residual
        if progress > 0.3 && (res - mean_residual).abs() < 8.0 && res >= next_item_size as f64 {
            score -= 3.0;
        }
        // New: penalize bins whose residual will strand a large dead gap after this item
        if next_item_size > 0 && res >= next_item_size as f64 {
            let after = res - next_item_size as f64;
            if after > 0.0 && after < 3.0 {
                score -= 5.0 + 6.0 * progress;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, but with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: post_residual squared normalized, weighted by stream progress.
    // Late in the stream, small residuals matter more (less time to fill them).
    let quad = norm_pr * norm_pr * (200.0 + 300.0 * progress);
    score += quad;

    // Smooth cubic interaction: reward tight fits more aggressively as progress advances
    let tight = (1.0 - norm_pr).powi(3);
    score -= tight * (60.0 + 120.0 * progress);

    // Penalize residual that cannot fit the next item (smooth via polynomial of mismatch)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let mismatch = (ns - pr) / cap;
            score += mismatch * mismatch * 150.0;
        } else {
            // Reward leaving room for the next item, smoothly
            let fit = (pr - ns) / cap;
            score -= (1.0 - fit) * 40.0;
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 80.0 + 60.0 * progress;
    } else {
        // Mild penalty when many bins fit, to prefer the best-fit one
        score += (fitting_bins_count as f64).ln() * 5.0;
    }

    // Coupling with mean residual: bins far below mean residual are "dirtier" targets late
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 50.0 * (0.5 + progress);

    // Mild penalty for opening new bins early (empty-bin candidate)
    if bin_residual == bin_capacity {
        score += 30.0 + 90.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Encourage consolidation: more open bins -> favor filling existing ones
    score -= (open_bins_count as f64).powi(2) * 0.05 * progress;

    score
}

