    // Mild attraction to bins whose residual is near the mean (balanced state).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Class-based tiebreak: prefer leaving residuals in high-utility classes (>=20).
    if class >= 2.0 {
        score -= 0.5 * class;
    }

    score
}

