    // Open-bins pressure
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
    score += pressure * 0.35;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
