        else if gap < 30.0 {
            score += 10.0;
        }
        // Large leftover space is mildly good (still usable).
        else {
            score -= 5.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to the item size (packing efficiency).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large and current residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_residuals = mean_residual < item_size as f64 * 0.6;
