    } else if gap < 5.0 {
        score -= 100.0;
    } else if gap < 24.0 {
        score += 54.0 - gap * 1.35;
    } else if gap < 42.0 {
        score += (42.0 - gap) * 0.36;
    } else if gap < 70.0 {
        score += (gap - 42.0) * 0.06;
    } else {
        score += (gap - 70.0) * 0.12;
    }

    // Small leftover shaping
    if post_residual > 0 && post_residual < 8 {
        score += 70.0 + (8 - post_residual) as f64 * 9.0;
    } else if post_residual >= 8 && post_residual < 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 32.0;
        } else {
            score += 18.0;
        }
    } else if post_residual >= 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        if post_residual > 55 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Lookahead: exact-fit chains for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 52.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 20.0;
        } else if gap > 0.0 && gap < nxt {
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0;
            }
            if fitting_bins_count <= 1 {
                score += 6.0;
            }
        }
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 22.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 7.0;
        }
        if gap >= nxt {
            let after = gap - nxt;
            if after > 0.0 && after <= 6.0 {
                score -= 16.0;
            } else if after >= 10.0 && after <= 20.0 {
                score -= 8.0;
            } else if after > 50.0 {
                score += 5.0;
            } else if after > 34.0 && after < 50.0 {
                score += 2.5;
            }
        }
        if gap >= nxt + nxt && (gap - nxt - nxt) < 6.0 {
            score -= 11.0;
        }
        if gap > 0.0 && gap < nxt && fitting_bins_count <= 1 {
            score += 10.0;
