        score += 25.0; // unusable sliver under minimum item size
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-mean residual (keep large residual bins free for big items).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Dynamic time horizon: early in the stream, keep bins flexible (favor balanced fills);
    // late in the stream, prioritize filling bins as completely as possible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 8.0 * (1.0 - progress) * ((bin_residual as f64 - bin_capacity as f64 / 2.0).abs() / (bin_capacity as f64 / 2.0));

    // Many open bins: encourage consolidation to avoid bin sprawl.
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && mean_residual > item_size as f64 * 1.15;
        if decent_fit_exists {
            score += 35.0; // discourage opening a new bin when decent fits exist
        } else {
            score -= 5.0; // mildly encourage a fresh bin over a terrible fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let gap = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 220.0;
    } else if gap < 5.0 {
        score -= 100.0;
    } else if gap < 24.0 {
        score += 54.0 - gap * 1.35;
    } else if gap < 42.0 {
        score += (42.0 - gap) * 0.36;
    } else if gap < 70.0 {
        score += (gap - 42.0) * 0.06;
    } else {
        score += (gap - 70.0) * 0.12;
    }

    // Dead-space avoidance with graded penalties (tuned small-leftover shaping)
    if post_residual > 0 && post_residual < 8 {
        score += 70.0 + (8 - post_residual) as f64 * 9.0;
    } else if post_residual >= 8 && post_residual < 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 32.0;
        } else {
            score += 18.0;
        }
    } else if post_residual >= 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        if post_residual > 55 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Lookahead: exact-fit chains for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 52.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 20.0;
        } else if gap > 0.0 && gap < nxt {
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0;
            }
            if fitting_bins_count <= 1 {
                score += 6.0;
            }
        }
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 22.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 7.0;
        }
        // post-placement remainder shaping
        if gap >= nxt {
            let after = gap - nxt;
            if after > 0.0 && after <= 6.0 {
                score -= 16.0;
            } else if after >= 10.0 && after <= 20.0 {
                score -= 8.0;
            } else if after > 50.0 {
                score += 5.0;
            } else if after > 34.0 && after < 50.0 {
                score += 2.5;
            }
        }
        // two-step lookahead: residual hosts next two items
        if gap >= nxt + nxt && (gap - nxt - nxt) < 6.0 {
            score -= 11.0;
        }
        if gap > 0.0 && gap < nxt && fitting_bins_count <= 1 {
            score += 10.0;
        }
        // NEW: triple-chain lookahead for medium residuals
        if gap >= nxt * 2.0 && (gap - nxt * 2.0) < 3.0 {
            score -= 14.0;
        }
    }

    // Open-bins pressure
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
    score += pressure * 0.4;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: open fresh bin only when the fit would be terrible
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.56 * bin_capacity as f64;
        let gate = 12.0 - 4.0 * progress;
