        if progress > 0.3 && (res - mean_residual).abs() < 8.0 && res >= next_item_size as f64 {
            score -= 3.0;
        }
        // NEW: reward bins whose residual is a multiple-friendly target for next item
        if next_item_size > 0 && res >= next_item_size as f64 {
            let r = res % next_item_size as f64;
            if r < 1.0 {
                score -= 5.0;
            }
        }
    }

    score
}

