    // Deviation from mean residual: prefer atypical bins slightly.
    score += 2.0 * (pr - mean_residual) / cap;

    // Mild pressure to close near-full bins late in stream.
    score += 5.0 * progress * x;

    // New-bin candidate: penalize opening new bins when alternatives exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

