    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 + 1.5 * progress * progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * (1.0 + progress) * 15.0;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
