pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (mod 10) are more likely to be filled later.
    let residue_class = post_residual % 10;
    score -= (10 - residue_class) as f64 * 0.6; // prefer residues near multiples of 10

    // Penalize large post residual strongly (wasted capacity)
