        score += (post_residual - bin_capacity / 2) as f64 * 0.8;
    }

    // Reward near-perfect fits
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (creates a perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            let nc = next_post % 10;
            score -= (10 - nc) as f64 * 0.4;
            score += next_post as f64 * 0.3;
        } else {
            // next item won't fit here; penalize leaving mid-range gaps
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or open bins are already crowded with small residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = bin_capacity as f64
            - item_size as f64 * 1.2
            - progress * 10.0
            - crowding * 20.0;
        if fitting_bins_count > 0 && item_size <= 40 {
            score += 12.0; // discourage new bin for small items when others fit
        }
    }

    // Slight tie-break toward tighter bins overall
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

