        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 38.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 7.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 4.0;
        }
        if res > 70.0 && next_item_size as f64 > res {
            score += 6.0;
        }
        if res > 45.0 && res < 70.0 && next_item_size as f64 > res && progress > 0.3 {
            score += 3.0;
        }
        // Zero-waste handoff
        if next_item_size > 0 && (res - next_item_size as f64).abs() < 1.0 {
            score -= 7.0 + 4.0 * progress;
        }
        // Near-miss residual: next item barely misses this bin
        if next_item_size > 0 && res < next_item_size as f64 && next_item_size as f64 - res <= 5.0 {
            score += 4.0;
        }
        // Mean-aligned reusable residual
        if progress > 0.3 && (res - mean_residual).abs() < 8.0 && res >= next_item_size as f64 {
            score -= 3.0;
