            let waste = res - next_item_size as f64;
            if waste <= 3.0 {
                score -= 5.0 + 3.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below ~10 (min item size) are dead.
    if post_residual < 10 {
        score -= 25.0; // perfect or near-perfect closure is excellent
    } else if post_residual <= 20 {
        // gap usable only by tiny items: mild penalty
        score += (20.0 - post_residual as f64) * 0.8;
    } else {
        // larger gaps: reward keeping them, but scale by how well next item fits
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 2.0; // gap can host the lookahead item
