    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() * 8.0 + 5.0;
        score += pressure;
        // but if no existing bin fits well, new bin becomes viable
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // using existing bins relieves pressure, more so when many bins are open
        score -= (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 4.0;
    }

    // Prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (10.0 - post_residual as f64).max(0.0) * 0.5;

    score
}

