}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 100.0; // perfect fill
    } else {
        // wasted space relative to smallest plausible item
        let waste = post_residual as f64;
        score += 0.25 * waste;
        // extra penalty if waste falls in "awkward" band (too small for mid items)
        if waste > 0.0 && waste < 20.0 {
            score += 15.0 * (1.0 - waste / 20.0);
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave a large gap
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 25.0 + 45.0 * progress;
        // but if mean residual is very low (open bins nearly full), new bin is fine
        score -= 30.0 * (1.0 - (mean_residual / bin_capacity as f64)).min(1.0).max(0.0);
    } else {
        // existing bin: reward more as stream progresses
        score -= 20.0 * progress;
    }

    // Many open bins: encourage filling them down (reduce bin count pressure).
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Global residual alignment: prefer bins whose residual is near mean (balanced use),
    // but reward using the fullest bin (smallest residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
