    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 52.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 20.0;
        } else if gap > 0.0 && gap < nxt {
