#[inline]
fn pressure_gate(open_bins_count: usize, progress: f64) -> f64 {
    open_bins_count as f64 * (0.4 + 0.85 * progress)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dead space that is too small to be reusable
    // (below the minimum item size 1..=100 -> threshold ~ small) is worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny slivers are dead space
    }

    // Harmonic class of the post residual: which "capacity fraction" band does it fall in?
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual % quarter == 0 {
        score -= 25.0; // residual is a clean capacity fraction: highly reusable
    } else if post_residual % 10 == 0 {
        score -= 15.0; // multiple of 10: commonly matched by item sizes
    } else if post_residual > half {
        score -= 10.0; // large residual stays usable
    } else if post_residual < quarter {
        score += 20.0; // small awkward residual
    }

    // Modulo harmony with the next item (lookahead pairing)
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly or nearly: strong reward
        if next_item_size == post_residual {
            score -= 45.0;
        } else {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 40.0; // creates a fresh sliver
            } else {
                score -= gap as f64 * 0.5; // decent chain fit
            }
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's residual anyway; residual class matters
        if post_residual >= bin_capacity - item_size && item_size <= half {
            score += 15.0; // left a big hole but item was small
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    if bin_residual == bin_capacity {
        // neutral baseline; penalize slightly so we only open when open bins score worse
        score += 30.0;
        // but early in the stream, having many bins is fine to build a portfolio
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 && open_bins_count < 4 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual = tighter bin)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for already-open bins as the stream matures
    if bin_residual < bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

