        score += 70.0 + (8 - post_residual) as f64 * 9.0;
    } else if post_residual >= 8 && post_residual < 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 32.0;
        } else {
            score += 18.0;
        }
    } else if post_residual >= 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        if post_residual > 55 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Lookahead: exact-fit chains for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 52.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 20.0;
        } else if gap > 0.0 && gap < nxt {
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0;
            }
            if fitting_bins_count <= 1 {
                score += 6.0;
            }
        }
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 22.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 7.0;
        }
        // post-placement remainder shaping
        if gap >= nxt {
            let after = gap - nxt;
            if after > 0.0 && after <= 6.0 {
                score -= 16.0;
            } else if after >= 10.0 && after <= 20.0 {
                score -= 8.0;
            } else if after > 50.0 {
                score += 5.0;
            } else if after > 34.0 && after < 50.0 {
                score += 2.5;
            }
        }
        // two-step lookahead: residual hosts next two items
        if gap >= nxt + nxt && (gap - nxt - nxt) < 6.0 {
            score -= 11.0;
        }
        if gap > 0.0 && gap < nxt && fitting_bins_count <= 1 {
            score += 10.0;
        }
    }

    // Open-bins pressure
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);
    score += pressure * 0.4;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: open fresh bin only when the fit would be terrible
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.56 * bin_capacity as f64;
        let gate = 12.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 46.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 38.0;
        }
        if open_bins_count > 14 && poor_fit {
            score -= 8.0;
        }
        if progress > 0.8 && slack > 0.45 * bin_capacity as f64 {
            score += 14.0;
        }
        if progress > 0.85 && slack > 0.3 * bin_capacity as f64 {
            score += 20.0;
        }
        if progress > 0.25 && progress < 0.7 && mean_residual > 30.0 && slack > 0.4 * bin_capacity as f64 {
            score += 8.0;
        }
    }

    // Mean residual coupling
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late-stream tightening: prefer filling existing bins near the end
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 14.0 * progress;
    }

    // Residual deviation shaping for open bins
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 38.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 7.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 4.0;
        }
        // penalize large stranded residuals no plausible item can fill
        if res > 70.0 && next_item_size as f64 > res {
            score += 6.0;
        }
        if res > 45.0 && res < 70.0 && next_item_size as f64 > res && progress > 0.3 {
            score += 3.0;
        }
        if next_item_size > 0 && (res - next_item_size as f64).abs() < 1.0 {
            score -= 7.0 + 4.0 * progress;
        }
        if next_item_size > 0 && res < next_item_size as f64 && next_item_size as f64 - res <= 5.0 {
            score += 4.0;
        }
        if progress > 0.3 && (res - mean_residual).abs() < 8.0 && res >= next_item_size as f64 {
            score -= 3.0;
        }
        // NEW: pair-harmony shaping — reward bins whose residual after this item
        // plus next item lands in the highly reusable 10-30 band
        if next_item_size > 0 && gap >= next_item_size as f64 {
            let two = gap - next_item_size as f64;
            if two >= 10.0 && two <= 30.0 {
                score -= 5.0 + 3.0 * (1.0 - progress);
            }
        }
        // NEW: penalize residuals that will strand near mid-gap with no follow-up
        if res >= 25.0 && res <= 40.0 && next_item_size as f64 > res && progress < 0.5 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty when post_residual falls into
    // unusable small gaps. Items are 1..=100, so any gap < 1 is impossible, but
    // gaps small relative to typical item sizes waste capacity. Treat gaps that
    // cannot fit the next item (when lookahead is available) as dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Smooth penalty on small gaps even without lookahead: gaps under ~15 are
    // unlikely to be filled by typical items.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // Open-bins pressure: penalize placements into already-crowded bin sets
    // slightly, encouraging consolidation into fewest bins.
    score += open_bins_count as f64 * 0.1;

    // New-bin candidate: make opening a fresh bin moderately expensive so it is
    // chosen only when no open bin offers a good fit. Scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 10.0 * progress;
        // But if the item is large and fits perfectly in a fresh bin, allow it.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Slight preference for bins with residuals close to mean (balance load),
    // nudging toward tighter consolidation.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

