pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fits.
            score -= 150.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit: penalize dead space a bit more.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize creating unusable slivers (dead space below the minimum item size).
    if post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: penalize unless it produces a great 2-step chain.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && post_residual <= next_item_size {
            score -= 200.0;
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    score
}

