        score += 45.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Coupling with mean residual: if this bin is far below the mean
    // residual (already fragmented), discourage adding to it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += 0.15 * diff;
    } else {
        score += 0.05 * diff; // small reward for using fuller-than-average bins
    }

    // Mild pressure to keep the number of open bins bounded.
    score += 0.5 * open_bins_count as f64;

    // Small tie-breaker on residual class: prefer bins whose residual class
    // is closest to the item size class.
    let item_class = item_size / cap_class.max(1);
    let class_gap = (res_class as i64 - item_class as i64).unsigned_abs() as f64;
    score += 2.0 * class_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let gap = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 220.0;
    } else if gap < 5.0 {
        score -= 100.0;
    } else if gap < 24.0 {
        score += 54.0 - gap * 1.35;
    } else if gap < 42.0 {
        score += (42.0 - gap) * 0.36;
    } else if gap < 70.0 {
        score += (gap - 42.0) * 0.06;
    } else {
        score += (gap - 70.0) * 0.12;
    }

    // Small leftover shaping
    if post_residual > 0 && post_residual < 8 {
        score += 70.0 + (8 - post_residual) as f64 * 9.0;
    } else if post_residual >= 8 && post_residual < 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 36.0;
        } else {
            score += 18.0;
        }
    } else if post_residual >= 18 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        if post_residual > 55 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Lookahead: exact-fit chains for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 0.5 {
            score -= 56.0;
        } else if gap >= nxt && gap - nxt < 14.0 {
            score -= 22.0;
        } else if gap > 0.0 && gap < nxt {
            if gap < 24.0 {
                score += 24.0;
            } else {
                score += 7.0;
            }
            if fitting_bins_count <= 1 {
                score += 6.0;
            }
        }
        if gap >= nxt * 1.5 && gap < 60.0 {
            score -= 6.0;
        }
        if gap >= nxt && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        let chain = item_size as f64 + nxt;
        if bin_residual as f64 >= chain && (bin_residual as f64 - chain) < 4.0 {
            score -= 22.0;
        }
        if gap >= nxt && gap - nxt < 7.0 && fitting_bins_count > 1 {
            score -= 8.0;
        }
        if gap >= nxt {
            let after = gap - nxt;
            if after > 0.0 && after <= 6.0 {
                score -= 18.0;
            } else if after >= 10.0 && after <= 20.0 {
                score -= 8.0;
            } else if after > 50.0 {
                score += 5.0;
            } else if after > 34.0 && after < 50.0 {
                score += 2.5;
            }
        }
        if gap >= nxt + nxt && (gap - nxt - nxt) < 6.0 {
            score -= 11.0;
        }
        if gap > 0.0 && gap < nxt && fitting_bins_count <= 1 {
            score += 10.0;
        }
    }

    // Open-bins pressure
    let pressure = open_bins_count as f64 * (0.4 + 0.85 * progress);

    // Only-bin reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: open fresh bin only when the fit would be terrible
    if bin_residual == bin_capacity {
        let slack = bin_capacity as f64 - item_size as f64;
        let poor_fit = slack > 0.56 * bin_capacity as f64;
        let gate = 12.0 - 4.0 * progress;
        let leftover_hosts_next = next_item_size > 0 && gap >= next_item_size as f64;
        if poor_fit && pressure < gate && !leftover_hosts_next {
            score -= 50.0;
        } else if poor_fit {
            score -= 3.0;
        } else {
            score += 38.0;
        }
        if open_bins_count > 14 && poor_fit {
            score -= 8.0;
        }
        if progress > 0.8 && slack > 0.45 * bin_capacity as f64 {
            score += 14.0;
        }
        if progress > 0.85 && slack > 0.3 * bin_capacity as f64 {
            score += 20.0;
        }
        if progress > 0.25 && progress < 0.7 && mean_residual > 30.0 && slack > 0.4 * bin_capacity as f64 {
            score += 8.0;
        }
        // Dead-space coupling: prefer a new bin when existing mean residual is already tight
        if mean_residual < 18.0 && slack > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Mean residual coupling
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late-stream tightening
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 14.0 * progress;
    }

    // Residual deviation shaping for open bins
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 38.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 7.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 4.0;
        }
        if res > 70.0 && next_item_size as f64 > res {
            score += 6.0;
        }
        if res > 45.0 && res < 70.0 && next_item_size as f64 > res && progress > 0.3 {
            score += 3.0;
        }
        // Zero-waste handoff
        if next_item_size > 0 && (res - next_item_size as f64).abs() < 1.0 {
            score -= 7.0 + 4.0 * progress;
        }
        // Near-miss residual: next item barely misses this bin
        if next_item_size > 0 && res < next_item_size as f64 && next_item_size as f64 - res <= 5.0 {
            score += 4.0;
        }
        // Mean-aligned reusable residual
        if progress > 0.3 && (res - mean_residual).abs() < 8.0 && res >= next_item_size as f64 {
            score -= 3.0;
        }
        // Dead-space penalty: residuals that cannot host the next item become waste
        if next_item_size > 0 && res < next_item_size as f64 && res > 0.0 && progress < 0.6 {
            score += (next_item_size as f64 - res) * 0.15;
        }
    }

    score
}

