    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // New bin candidate: make it slightly unattractive unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if no open bin fits well, allow opening a new bin for small post_residual.
        if post_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    score
}

