    let mut score = post_residual as f64;

    // Core: reward near-perfect fills strongly (dead space penalty is super-linear).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 0.5);

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            // partial lookahead fit: reward proportional to how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize wasting space the next item could have used elsewhere
            score += 8.0;
        }
    }

    // Compare post_residual against mean residual: avoid making this bin an outlier of wasted space.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

