    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * fill_ratio;           // big items justify fresh bins
        score += 15.0 * (1.0 - fill_ratio);   // small items should reuse open bins
        score += 10.0 * progress;             // late in stream, prefer consolidation
    }

    // Slight preference for tighter bins when many are open.
    score += 0.05 * open_bins_count as f64 * fill_ratio;

