    // Open-bin pressure: when many bins are open, prefer tightening existing bins
    // rather than spreading items; when few bins are open, mild pressure to fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin is far tighter than average, favor it.
    score -= 0.3 * (mean_residual - post_residual as f64);

