}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let fit_frac = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: tight fits (small post_residual) rewarded super-linearly.
    let tight = 1.0 - pr / cap; // closeness of fit in [0,1)
    score -= 12.0 * tight * tight * (1.0 + 0.5 * progress);

    // Penalize dead space that is too small to be useful later, smooth cubic term.
    let dead = (pr / cap).powi(3);
    score += 20.0 * dead * (1.0 - fit_frac);

    // Lookahead: reward if next item fits the post-residual, penalize if it nearly misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (1.0 - pr / nxt) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 6.0 * progress;
