}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness ratio: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when fit is bad; few open bins -> favor using existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let gap_fit = (post_residual - next_item_size) as f64;
        if gap_fit < 10.0 {
            score -= 35.0 - 2.0 * gap_fit;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: prefer keeping it closed unless this bin's fit is poor
    // or the stream is early with plenty of room to consolidate later.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Discourage opening a new bin when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual as f64 >= 0.0 {
            score += 25.0;
        }
    }

    score
}

