            // Penalize dead space that the next item cannot use.
            score += 0.6 * gap;
            // If next item fits exactly-ish, extra reward proportional to closeness.
            if next_item_size <= post_residual {
                score -= 12.0 * (1.0 - gap / post_residual as f64);
