        }
        if open_bins_count > 14 && poor_fit {
            score -= 8.0;
        }
        if progress > 0.8 && slack > 0.45 * bin_capacity as f64 {
            score += 14.0;
        }
        if progress > 0.85 && slack > 0.3 * bin_capacity as f64 {
            score += 20.0;
        }
        if progress > 0.25 && progress < 0.7 && mean_residual > 30.0 && slack > 0.4 * bin_capacity as f64 {
            score += 8.0;
        }
        // NEW: mid-stream, avoid opening a bin whose slack barely exceeds next item
        if progress > 0.35 && progress < 0.75 && next_item_size > 0
            && slack >= next_item_size as f64 && slack < next_item_size as f64 + 10.0 {
