        }
    }

    // Mean residual coupling
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late-stream tightening
    if progress > 0.72 && bin_residual != bin_capacity {
        score -= 14.0 * progress;
    }

    // Residual deviation shaping for open bins
    let res = bin_residual as f64;
    if res != bin_capacity as f64 {
        let dev = ((res - mean_residual).abs()) / bin_capacity as f64;
        score += dev * 6.0;
        if open_bins_count > 8 {
            score += dev * dev * 38.0;
        }
        if res < item_size as f64 + 4.0 {
            score -= 4.0;
        }
        if res < 12.0 && next_item_size as f64 > res {
            score -= 7.0;
        }
        if progress > 0.4 && progress < 0.75 && res >= 20.0 && res <= 34.0 {
            score -= 4.0;
        }
        if res > 70.0 && next_item_size as f64 > res {
            score += 6.0;
        }
        if res > 45.0 && res < 70.0 && next_item_size as f64 > res && progress > 0.3 {
            score += 3.0;
        }
        // Zero-waste handoff
        if next_item_size > 0 && (res - next_item_size as f64).abs() < 1.0 {
            score -= 7.0 + 4.0 * progress;
        }
        // Near-miss residual: next item barely misses this bin
        if next_item_size > 0 && res < next_item_size as f64 && next_item_size as f64 - res <= 5.0 {
            score += 4.0;
        }
        // Mean-aligned reusable residual
        if progress > 0.3 && (res - mean_residual).abs() < 8.0 && res >= next_item_size as f64 {
            score -= 3.0;
        }
        // NEW: penalize large residuals that no plausible item can use late in the stream
        if progress > 0.6 && next_item_size > 0 && res > next_item_size as f64 + 25.0 {
            score += 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Tightness: normalized fill of the bin by this item.
    let fill = item_size as f64 / residual.max(1.0);
    score -= 12.0 * fill * fill;

    // Dead-space penalty: post_residual too small to be useful later (min item 1).
    // Penalize residuals in the awkward small range.
    if post > 0.0 && post < 10.0 {
        score += 18.0 * (10.0 - post) / 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= post {
            let slack = post - ni;
            if slack == 0.0 {
                score -= 40.0; // chain fit: perfect two-item packing
            } else {
                score -= 8.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item won't fit here: penalize leaving a large unusable remainder.
            score += 6.0 * (ni - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier, penalize mediocre fits.
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0) * (1.0 - fill);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins above the mean (drain the fullest bins).
    if open_bins_count > 1 {
        let above_mean = residual - mean_residual;
        score -= 2.5 * above_mean / cap;
        // Crowding pressure: when many bins are open, tighten selection.
        score += 0.4 * (open_bins_count as f64).ln() * (post / cap);
    }

    // Time horizon: early in the stream, be conservative (leave room);
    // late in the stream, pack aggressively (few future consequences).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill;
    score += 6.0 * (1.0 - progress) * (post / cap);

    // New-bin candidate: only attractive when this bin is empty and the item is huge,
    // or when no open bin gives a decent fit.
    if residual == cap {
        // Empty bin baseline: penalize unless item is large relative to capacity.
        score += 20.0 - 15.0 * (item_size as f64 / cap);
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score -= 10.0; // fresh bin can host a clean pair
        }
    }

    score
}

